        <span class="gv-tb gv-primary" data-a="edit" title="编辑这一楼的原文">编辑</span>
        <span class="gv-tb" data-a="copy" title="复制这一楼内容">复制</span>
        <span class="gv-tb" data-a="up" title="楼层上移">上移楼层</span>
        <span class="gv-tb" data-a="down" title="楼层下移">下移楼层</span>
        <span class="gv-tb gv-toggle" data-a="toggle-user-avatar" id="btnUa" title="对话轮到TA说话时显示TA的头像">显示头像</span>
        <!--gv-audio--><span class="gv-tb" data-a="volume" id="btnVol" title="调整 BGM / 音效 的音量">调整音量</span><!--/gv-audio-->
        <span class="gv-tb gv-danger" data-a="delete" title="删除这一楼">删除楼层</span>
      </div>
    </div>
    <!--gv-audio--><div class="gv-vol" id="vol">
