```css
/* ============================================================
   酒馆 Galgame 楼层界面 — 样式
   全部类名以 gv- 前缀隔离
   ============================================================ */
.gv-root, .gv-root * { box-sizing: border-box; }
.gv-root {
  --gv-accent: #ff8fb1;
  --gv-panel: rgba(16, 18, 28, 0.82);
  --gv-text: #f2f3f7;
  display: flex; justify-content: center;
  margin: 0;
  font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans SC", system-ui, sans-serif;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

/* ---------- 手机外框 ---------- */
.gv-phone {
  position: relative;
  width: min(100%, 400px);
  aspect-ratio: 9 / 19.5;
  max-height: 86vh;
  border-radius: 26px; overflow: hidden;
  background: #05060a;
  box-shadow: 0 10px 34px rgba(0,0,0,.55), 0 0 0 1px rgba(255,255,255,.10) inset;
  isolation: isolate; cursor: pointer;
}
/* 顶部那个"灵动岛"黑药丸已去掉 */

/* ---------- 背景 ---------- */
.gv-bgs { position: absolute; inset: 0; z-index: 1; }
.gv-bg {
  position: absolute; inset: 0; background-size: cover; background-position: center;
  opacity: 0; transition: opacity .7s ease; transform: scale(1.04);
}
.gv-bg.gv-on { opacity: 1; }
.gv-vignette {
  position: absolute; inset: 0; z-index: 2; pointer-events: none;
  background:
    radial-gradient(120% 70% at 50% 0%, transparent 40%, rgba(0,0,0,.35) 100%),
    linear-gradient(to bottom, rgba(0,0,0,.18) 0%, transparent 22%, transparent 55%, rgba(0,0,0,.55) 100%);
}
.gv-dim { position: absolute; inset: 0; z-index: 3; pointer-events: none; background: #000; opacity: 0; transition: opacity .45s ease; }
.gv-dim.gv-on { opacity: .62; }
.gv-flash { position: absolute; inset: 0; z-index: 30; pointer-events: none; background: #fff; opacity: 0; }
.gv-flash.gv-go { animation: gv-flash .5s ease; }
@keyframes gv-flash { 0%{opacity:.9} 100%{opacity:0} }

/* ---------- 立绘 ---------- */
/* ---------- 立绘: 一个站位一张, 支持多角色同框 ---------- */
.gv-stage { position: absolute; inset: 0; z-index: 4; pointer-events: none; }
.gv-sprite {
  position: absolute; left: var(--gv-x, 50%);
  bottom: calc((100 - var(--gv-y, 100)) * 1%);
  width: var(--gv-w, 100%); height: var(--gv-h, 100%);
  transform: translateX(-50%) scale(var(--gv-s, 1));
  transform-origin: 50% 100%; transition: filter .35s ease, opacity .35s ease;
  display: flex; align-items: flex-end; justify-content: center;   /* 图比框宽时也要居中, 不能偏到一边 */
}
.gv-sprite img {
  height: 100%; width: auto; max-width: none; display: block;
  object-fit: contain; object-position: bottom center;
  filter: saturate(1.04) contrast(1.02);
}
/* 多角色同框: 不是当前说话者的那张淡下去 */
.gv-sprite.gv-idle { opacity: .55; filter: brightness(.8) saturate(.85); }
/* ★ 演出动画必须在每一帧都带上 translateX(-50%) + scale(var(--gv-s)),
   否则动画会覆盖掉立绘的定位 transform —— 立绘就会"闪到天边去" */
.gv-sprite.gv-shake { animation: gv-shake .45s ease; }
@keyframes gv-shake {
  0%,100%{transform:translateX(-50%) translateX(0) scale(var(--gv-s,1))}
  20%{transform:translateX(-50%) translateX(-4px) scale(var(--gv-s,1))}
  45%{transform:translateX(-50%) translateX(4px)  scale(var(--gv-s,1))}
  70%{transform:translateX(-50%) translateX(-2px) scale(var(--gv-s,1))}
}
.gv-sprite.gv-jump { animation: gv-jump .5s ease; }
@keyframes gv-jump {
  0%{transform:translateX(-50%) translateY(0) scale(var(--gv-s,1))}
  35%{transform:translateX(-50%) translateY(-10px) scale(var(--gv-s,1))}
  65%{transform:translateX(-50%) translateY(0) scale(var(--gv-s,1))}
  82%{transform:translateX(-50%) translateY(-4px) scale(var(--gv-s,1))}
  100%{transform:translateX(-50%) translateY(0) scale(var(--gv-s,1))}
}
/* 呼吸式缩放: 放大一点点 -> 缩小一点点 -> 回位 (幅度很小, 不闪不飞) */
.gv-sprite.gv-zoom { animation: gv-zoom .9s ease-in-out; }
@keyframes gv-zoom {
  0%   { transform: translateX(-50%) scale(var(--gv-s,1)); }
  30%  { transform: translateX(-50%) scale(calc(var(--gv-s,1) * 1.045)); }
  60%  { transform: translateX(-50%) scale(calc(var(--gv-s,1) * 0.985)); }
  100% { transform: translateX(-50%) scale(var(--gv-s,1)); }
}
.gv-sprite.gv-dim { filter: brightness(.45) saturate(.6); }
.gv-bubble {
  position: absolute; top: 6%; right: 6%; z-index: 8; font-size: 30px; line-height: 1;
  animation: gv-bubble 1.5s ease forwards; filter: drop-shadow(0 3px 6px rgba(0,0,0,.5));
}
@keyframes gv-bubble {
  0%{opacity:0; transform: translateY(14px) scale(.5)}
  25%{opacity:1; transform: translateY(0) scale(1.15)}
  40%{transform: translateY(0) scale(1)}
  80%{opacity:1} 100%{opacity:0; transform: translateY(-16px) scale(1)}
}

/* ---------- 对话框 ---------- */
.gv-ui { position: absolute; left: 0; right: 0; bottom: 0; z-index: 10; padding: 0 8px 8px; }
.gv-box {
  position: relative; min-height: 30%; margin-bottom: 34px;   /* ★ 给右下角那排 HUD 留出位置, 对话框不跟它重叠 */
  border-radius: 16px;
  background: var(--gv-panel);
  backdrop-filter: blur(9px) saturate(1.2); -webkit-backdrop-filter: blur(9px) saturate(1.2);
  border: 1px solid rgba(255,255,255,.14);
  box-shadow: 0 -4px 24px rgba(0,0,0,.4);
  padding: 16px 15px 18px;
}
.gv-box.gv-has-uava { padding-left: 15px; }   /* 头像在右上角, 不再挤占文字 */
.gv-uava {
  position: absolute; top: -13px; right: 12px; left: auto; bottom: auto;
  width: 42px; height: 42px; border-radius: 11px; object-fit: cover;
  border: 1px solid rgba(255,255,255,.32); box-shadow: 0 3px 12px rgba(0,0,0,.5);
  background: #222;
}
.gv-name {
  position: absolute; top: -13px; left: 14px;
  padding: 3px 14px; border-radius: 999px;
  font-size: 14px; font-weight: 700; letter-spacing: .5px; color: #10121a;
  background: linear-gradient(135deg, #fff, var(--gv-accent));
  box-shadow: 0 3px 10px rgba(0,0,0,.35);
  white-space: nowrap; max-width: 70%; overflow: hidden; text-overflow: ellipsis;
}
.gv-name.gv-narr { background: linear-gradient(135deg,#dfe3ee,#8e97ad); }
.gv-name.gv-user { background: linear-gradient(135deg,#fff,#7fd1ff); }
.gv-text {
  margin: 6px 0 0; color: var(--gv-text);
  font-size: 16px; line-height: 1.72; letter-spacing: .3px;
  min-height: 4.5em; white-space: pre-wrap; word-break: break-word;
  text-shadow: 0 1px 3px rgba(0,0,0,.6);
}
.gv-text.gv-narr { font-style: italic; color: #c9ccdb; }
.gv-caret {
  display: inline-block; width: .55em; height: 1em; vertical-align: -2px;
  background: var(--gv-accent); opacity: 0; margin-left: 2px;
  animation: gv-caret 1s steps(1) infinite;
}
.gv-caret.gv-on { opacity: .9; }
@keyframes gv-caret { 50% { opacity: 0 } }

/* ★ HUD(进度点 + 自动/重播) 钉在画面右下角, 不再跟着点点/行数跑。
   以前它在对话框下面占一行普通流: 点点一多就把「自动/重播」顶出画面右边缘
   (实测 40 句顶出 42px、60 句顶出 222px, 按钮直接看不见)。
   现在 HUD 绝对定位(相对 .gv-ui, 而 .gv-ui 的底边就是画面底边) -> 永远在右下角;
   点点放不下就自己变窄/被裁, 按钮 flex:0 0 auto 永不移动。 */
.gv-hud {
  position: absolute; right: 8px; bottom: 8px; z-index: 12;
  display: flex; align-items: center; justify-content: flex-end; gap: 8px;
  max-width: calc(100% - 16px);
  color: rgba(255,255,255,.72); font-size: 12px;
}
.gv-dots { display: flex; gap: 4px; align-items: center; justify-content: flex-end; flex: 0 1 auto; min-width: 0; overflow: hidden; }
.gv-dot { flex: 0 1 5px; min-width: 2px; height: 5px; border-radius: 50%; background: rgba(255,255,255,.28); }
.gv-dot.gv-on { background: var(--gv-accent); transform: scale(1.5); }
.gv-btns { display: flex; gap: 6px; flex: 0 0 auto; }
.gv-btn {
  cursor: pointer; padding: 3px 10px; border-radius: 999px;
  background: rgba(255,255,255,.10); border: 1px solid rgba(255,255,255,.16);
  color: rgba(255,255,255,.85); font-size: 11px; transition: background .2s, transform .1s;
}
.gv-btn:hover { background: rgba(255,255,255,.2); }
.gv-btn:active { transform: scale(.94); }
.gv-btn.gv-active { background: var(--gv-accent); color: #10121a; font-weight: 700; }
.gv-next {
  position: absolute; right: 14px; bottom: 8px; color: var(--gv-accent);
  font-size: 13px; animation: gv-bob 1.1s ease-in-out infinite;
}
@keyframes gv-bob { 0%,100%{transform:translateY(0); opacity:.5} 50%{transform:translateY(4px); opacity:1} }

/* 隐藏酒馆原生楼层正文 */
.gv-hide { display: none !important; }
.gv-floor-host { margin: 0; position: relative; }

/* ============================================================
   整层替换模式
   ============================================================ */
#chat > .mes.gv-full {
  display: block !important;
  width: 100% !important; max-width: 100% !important; min-width: 0 !important;
  margin: 0 !important; padding: 0 !important;
  border: 0 !important; border-radius: 0 !important;
  background: transparent !important; background-image: none !important;
  box-shadow: none !important; backdrop-filter: none !important;
  /* #chat 是 flex column, 必须禁止收缩, 否则楼层会被压扁、内容溢出重叠 */
  flex: 0 0 auto !important;
  height: auto !important; min-height: auto !important; max-height: none !important;
}
#chat > .mes.gv-full { position: relative !important; }
/* 头像 / 滑动箭头等藏掉, 但"多选删除框"必须留着 */
#chat > .mes.gv-full > *:not(.mes_block):not(.for_checkbox) { display: none !important; }
#chat > .mes.gv-full > .for_checkbox {
  display: flex !important; align-items: center;
  position: absolute !important; left: 4px; top: 6px; z-index: 80;
