#chat > .mes.gv-full > .mes_block {
  display: block !important; position: relative !important;
  width: 100% !important; max-width: 100% !important;
  margin: 0 !important; padding: 0 !important;
  border: 0 !important; background: transparent !important; box-shadow: none !important;
  overflow: visible !important;
}
/* 原生正文 / 思维链 藏掉, 但 .ch_name 要留着装原生按钮 */
#chat > .mes.gv-full > .mes_block > *:not(.gv-floor-host):not(.ch_name) { display: none !important; }
#chat > .mes.gv-full > .mes_block > .gv-floor-host { display: block !important; width: 100% !important; }

/* 酒馆原生按钮条整个不要了 —— 用我们自己的 .gv-toolbar */
#chat > .mes.gv-full > .mes_block > .ch_name { display: none !important; }

/* ============================================================
