.gv-tb.gv-toggle.gv-on { background: #7fd1ff; color: #10121a; font-weight: 700; }
.gv-tb {
  cursor: pointer; padding: 1px 9px; border-radius: 6px; font-size: 11.5px;
  background: rgba(255,255,255,.10); border: 1px solid rgba(255,255,255,.14);
