/* gv-vol-v4 */
.gv-vol-x { position: absolute; top: 4px; right: 8px; width: 20px; height: 20px; line-height: 19px;
  text-align: center; border-radius: 6px; font-size: 15px; cursor: pointer; opacity: .7; background: rgba(255,255,255,.12); }
