/* AI 楼层: 编辑按钮下方弹出的气泡菜单 (在手机框里面) */
.gv-popup {
  display: none; position: absolute; top: calc(100% + 6px); right: 0;
  flex-direction: column; gap: 4px; padding: 7px; min-width: 106px;
  background: rgba(10,12,18,.94);
