@keyframes gv-b-pop {
  0% { transform: translate(-50%,-50%) scale(0); }
  60% { transform: translate(-50%,-50%) scale(calc(var(--gv-bs,1) * 1.25)); }
  100% { transform: translate(-50%,-50%) scale(var(--gv-bs,1)); } }
