  border: 1px solid rgba(255,255,255,.18); outline: none;
}
.gv-editor-btns { display: flex; gap: 8px; justify-content: flex-end; }

/* 玩家输入楼层: 黑色一行 + 向下展开的半透明区 (不再往右撑) */
.gv-userbar-wrap { display: block; }
