@keyframes gv-b-pop {
  0% { transform: translate(-50%,-50%) scale(0); }
  60% { transform: translate(-50%,-50%) scale(calc(var(--gv-bs,1) * 1.25)); }
  100% { transform: translate(-50%,-50%) scale(var(--gv-bs,1)); } }
@keyframes gv-b-left {
  0% { transform: translate(calc(-50% - 90px),-50%) scale(var(--gv-bs,1)); opacity: 0; }
  70% { transform: translate(calc(-50% + 8px),-50%) scale(var(--gv-bs,1)); opacity: 1; }
  100% { transform: translate(-50%,-50%) scale(var(--gv-bs,1)); opacity: 1; } }
@keyframes gv-b-diag {
  0% { transform: translate(calc(-50% + 70px), calc(-50% + 70px)) scale(calc(var(--gv-bs,1) * .6)); opacity: 0; }
  70% { transform: translate(calc(-50% - 6px), calc(-50% - 6px)) scale(calc(var(--gv-bs,1) * 1.06)); opacity: 1; }
  100% { transform: translate(-50%,-50%) scale(var(--gv-bs,1)); opacity: 1; } }
@keyframes gv-b-blink {
