.gv-sticker.gv-b-pop { animation: gv-b-pop .5s cubic-bezier(.2,1.5,.4,1) forwards; }
.gv-sticker.gv-b-left { animation: gv-b-left .5s cubic-bezier(.2,1.2,.4,1) forwards; }
.gv-sticker.gv-b-diag { animation: gv-b-diag .55s cubic-bezier(.2,1.2,.4,1) forwards; }
.gv-sticker.gv-b-blink { animation: gv-b-blink .9s ease forwards; }
