.gv-sheet-toast.bad{background:rgba(255,90,90,.95);color:#fff;}

/* ---- User 楼层那一支也要 border-box, 否则编辑框 width:100% + padding 会超出容器右侧被裁 ---- */
.gv-userbar-wrap, .gv-userbar-wrap * { box-sizing: border-box; }

/* ---- 模板版微调: iframe 里由内容决定高度 ---- */
.gv-root { align-items: flex-start; }
.gv-phone { max-height: none; }

/* ---- 自适应缩放: 容器比设计宽度窄时, JS 会设 --gv-scale, 整块按比例缩小 ---- */
.gv-root { transform: scale(var(--gv-scale, 1)); transform-origin: 50% 0; }
/* ★ 整页不许出原生滚动条 (楼层 iframe 右边缘那条丑的谷歌滚动条就是它) */
html, body { overflow: hidden !important; overflow-x: hidden; scrollbar-width: none; }
html::-webkit-scrollbar, body::-webkit-scrollbar { width: 0 !important; height: 0 !important; display: none !important; }
