  zoom: 'gv-zoom', 放大: 'gv-zoom', 拉近: 'gv-zoom',
  dim: 'gv-dim', 变暗: 'gv-dim', 暗: 'gv-dim',
  bubble: 'gv-bubble', 气泡: 'gv-bubble', 惊愕: 'gv-bubble',
